const ROOT=resolve(dirname(fileURLToPath(import.meta.url)),'..');
const IDS=Object.keys(EXPECTED.poems),REV=EXPECTED.publisher_revision,VRI=EXPECTED.vri_revision;
const checkout=process.env.APADANA_SOURCE_CHECKOUT,source={skip:!checkout,timeout:30000};
const sha=value=>createHash('sha256').update(value).digest('hex'),objectSha=value=>sha(JSON.stringify(value));
const originalFetch=globalThis.fetch,PRIVATE='SYNTHETIC_PRIVATE_FIVE_ā😀';
const altered=text=>(text[0]==='X'?'Y':'X')+text.slice(1);
afterEach(()=>{globalThis.fetch=originalFetch;liveCache.clear();});

function exactArtifacts(){
 const raw=new Map();
 for(const right of EXPECTED.rights){const bytes=readSixRegularRelative(checkout,right.path);assert.equal(bytes.length,right.bytes);assert.equal(sha(bytes),right.sha256);assert.equal(createHash('sha1').update('blob '+bytes.length+'\0').update(bytes).digest('hex'),right.git_blob_sha1);}
 for(const id of IDS){const g=EXPECTED.poems[id],bytes=readSixRegularRelative(checkout,g.raw_relative);assert.equal(bytes.length,g.raw_bytes);assert.equal(sha(bytes),g.raw_sha256);assert.equal(createHash('sha1').update('blob '+bytes.length+'\0').update(bytes).digest('hex'),g.raw_git_blob);raw.set(g.raw_url,bytes.toString('utf8'));}
 return raw;
}
function declaredCurrent(){
 assertCurrent389390SourceClosure(ROOT);const a=intake380Authority(ROOT),declared=JSON.parse(readFileSync(resolve(ROOT,'server/data/apadana.json')));
 requireMetadata382(APADANA_PROFILES,declared,ROOT);const now=intake382Authority(ROOT);assert.equal(now.ids.length,382);assert.deepEqual(now.historical380,intake380Authority(ROOT));assert.deepEqual(now.ids.slice(380),['tha-ap403','tha-ap404']);assert.equal(a.ids.length,380);assert.equal(a.historical375.ids.length,375);assert.equal(a.historical368.ids.length,368);assert.deepEqual(a.ids,a.historical375.ids.concat(IDS));
 for(const id of a.historical375.ids){assert.deepEqual(APADANA_PROFILES[id],a.historical375.profiles[id]);assert.deepEqual(declared.links[id],a.historical375.links[id]);}
 for(const id of IDS){assert.equal(objectSha(APADANA_PROFILES[id]),EXPECTED.poems[id].profile_sha256);assert.equal(objectSha(declared.links[id]),EXPECTED.poems[id].link_sha256);}
 assert.deepEqual(a.approval.required_visible_qualifications,[{id:'tha-ap386',publisher_poem:384,note_number:4,source_issue:'unfinished_parenthesis_at_original_eof',verbatim_note_sha256:'f05875673e20155d7db9717238d066cbb595f88618d4ac4a7672caec8854fc29',mapping_notice:EXPECTED.poems['tha-ap386'].defect_notice}]);
 for(const id of['tha-ap360','tha-ap375','tha-ap381','tha-ap382','tha-ap384','tha-ap389','tha-ap390','tha-ap391','tha-ap392'])assert.equal(Object.hasOwn(APADANA_PROFILES,id),false,'Existing held publisher source remains inactive');
 return declared;
}

function normalized(id,value){assert.equal(value.title,EXPECTED.poems[id].title);normalizedContent(id,value);}
function normalizedWidget(id,value){assert.equal(Object.hasOwn(value,'title'),false);assert.equal(Object.hasOwn(value,'text_id'),false);assert.equal(Object.hasOwn(value,'limit'),false);assert.equal(value.reference,APADANA_PROFILES[id].reference);normalizedContent(id,value);}
function normalizedContent(id,value){
 const g=EXPECTED.poems[id];assert.equal(sha(value.text),g.body_sha256);assert.equal(value.text.length,g.characters);
 assert.equal(objectSha(value.translator_notes),g.notes_sha256);assert.deepEqual(value.translator_notes.map(n=>n.number),g.note_numbers);
 for(const row of g.notes){const actual=value.translator_notes.find(n=>n.number===row.number);assert.ok(actual);assert.equal(sha(actual.text),row.sha256);assert.equal(actual.text.length,row.characters);}
 for(const row of g.notes){const owners=value.text.split('\n\n').flatMap((text,i)=>text.includes('[Note '+row.number+']')?[i]:[]);assert.deepEqual(owners,[row.owner_paragraph_index0]);}
 if(id==='tha-ap386'){const note=value.translator_notes.find(n=>n.number===4);assert.equal(sha(note.text),'f05875673e20155d7db9717238d066cbb595f88618d4ac4a7672caec8854fc29');assert.equal(note.text.length,127);assert.equal(g.defect_notice,APADANA_PROFILES[id].mapping_notes[2]);}
 assert.equal(sha(value.publisher_paratext),g.paratext_sha256);assert.equal(value.publisher_paratext.length,g.paratext_characters);
 for(const key of EXPECTED.absent_scopes)assert.equal(Object.hasOwn(value,key),false);
}
function transport(raw,calls){
 liveCache.clear();globalThis.fetch=async(input,init={})=>{const url=typeof input==='string'?input:input.href;assert.ok(raw.has(url),'Only the five pinned official sources may be fetched');assert.ok(!url.includes(PRIVATE)&&!JSON.stringify(init).includes(PRIVATE));calls.push(url);return new Response(raw.get(url),{headers:{'content-type':'text/plain; charset=utf-8'}});};
}
function apiMetadata(id,value){for(const[key,expected]of Object.entries(EXPECTED.poems[id].source_metadata))assert.deepEqual(value[key],expected);}
function positiveHost(host,widget,id){
 host.output(widget);assert.ok(host.elements.english.textContent.includes(widget.english.text));assert.ok(host.elements.pali.textContent.includes(widget.pali.segments[0].text));
 const list=host.elements.english.children.find(n=>n.tagName==='ol');assert.ok(list);assert.equal(objectSha(list.children.map(n=>({number:n.value,text:n.textContent}))),EXPECTED.poems[id].notes_sha256);
 for(const notice of APADANA_PROFILES[id].mapping_notes)assert.ok(host.elements.english.textContent.includes(notice));
 if(id==='tha-ap386')assert.ok(host.elements.english.textContent.includes(EXPECTED.poems[id].defect_notice),'VM retained exact published-note qualification; real normal-CSP visibility has its separate installed gate');
}
function refusedHost(host,widget,label='same_consumed_object'){assert.match(host.elements.english.textContent,/No English|No translation/,label);assert.ok(!host.elements.english.textContent.includes(widget.english.text),label+' no stale English');assert.ok(!host.elements.english.textContent.includes(widget.english.translator_notes[0].text),label+' no stale notes');assert.ok(host.elements.pali.textContent.includes(widget.pali.segments[0].text),label+' current Pali remains');}
function corruptions(value){
 const notes=structuredClone(value);notes.translator_notes[0].text=altered(notes.translator_notes[0].text);
 const renumbered=structuredClone(value);renumbered.translator_notes[0].number=999;
 const reordered=structuredClone(value);[reordered.translator_notes[0],reordered.translator_notes[1]]=[reordered.translator_notes[1],reordered.translator_notes[0]];
 const body={...structuredClone(value),text:altered(value.text)};assert.equal(body.text.length,value.text.length);
 const paratext={...structuredClone(value),publisher_paratext:value.publisher_paratext?altered(value.publisher_paratext):' '};
 if(value.publisher_paratext)assert.equal(paratext.publisher_paratext.length,value.publisher_paratext.length);
 const extra=[];if(value.translation_id==='ap:chapter-3/poem-384'){const closed=structuredClone(value);closed.translator_notes.find(n=>n.number===4).text+=')';extra.push(['note4_invented_closing_parenthesis',closed,true],['note4_qualification_missing',{...structuredClone(value),mapping_notes:value.mapping_notes.filter(n=>n!==EXPECTED.poems['tha-ap386'].defect_notice)},true]);}
 return[
  ...extra, ['body_same_length',body,true],['paratext_same_length_or_empty_whitespace',paratext,true],['paratext_whitespace',{...structuredClone(value),publisher_paratext:' '.repeat(value.publisher_paratext.length||1)},true],
  ['note_text_same_length',notes,true],['note_number',renumbered,true],['note_order',reordered,true],['note_missing',{...structuredClone(value),translator_notes:value.translator_notes.slice(1)},true],
  ['license',{...structuredClone(value),license:'CC0'},true],['revision',{...structuredClone(value),translation_revision:'0'.repeat(40)},true],
  ['root_pin',{...structuredClone(value),root_sha256:'0'.repeat(64)},false],['foreign_summary',{...structuredClone(value),chapter_summary:{parent_id:'tha-ap375'}},true]
 ].map(([label,bad,apChoice])=>({label,bad,apChoice}));
}

